export function desaturate(color: string): string {
  if (!/^#[0-9a-fA-F]{6}$/.test(color)) {
    return color;
  }

  const red: number = parseInt(color.slice(1, 3), 16);
  const green: number = parseInt(color.slice(3, 5), 16);
  const blue: number = parseInt(color.slice(5, 7), 16);
  const maximum: number = Math.max(red, green, blue);
  const minimum: number = Math.min(red, green, blue);
  // HSL lightness is (max + min) / 2.  Keeping the integer portion is
  // equivalent to the channel quantisation used by the colour helpers.
  const lightness: number = Math.floor((maximum + minimum) / 2);
  const channel: string = lightness.toString(16).padStart(2, '0');

  return `#${channel}${channel}${channel}`;
}
export function rotateHue(color: string, degrees: number): string {
  if (!/^#[0-9a-fA-F]{6}$/.test(color)) {
    return color;
  }

  const red = parseInt(color.slice(1, 3), 16) / 255;
  const green = parseInt(color.slice(3, 5), 16) / 255;
  const blue = parseInt(color.slice(5, 7), 16) / 255;
  const maximum = Math.max(red, green, blue);
  const minimum = Math.min(red, green, blue);

  // There is no hue to rotate for a grey.  Besides being the natural HSL
  // result, returning here also preserves the exact channel value.
  if (maximum === minimum) {
    return color.toLowerCase();
  }

  const lightness = (maximum + minimum) / 2;
  const difference = maximum - minimum;
  const saturation = lightness > 0.5
    ? difference / (2 - maximum - minimum)
    : difference / (maximum + minimum);
  let hue: number;

  if (maximum === red) {
    hue = (green - blue) / difference + (green < blue ? 6 : 0);
  } else if (maximum === green) {
    hue = (blue - red) / difference + 2;
  } else {
    hue = (red - green) / difference + 4;
  }
  hue = hue * 60 + degrees;
  hue = ((hue % 360) + 360) % 360;

  const hueFraction = hue / 360;
  const first = lightness < 0.5
    ? lightness * (1 + saturation)
    : lightness + saturation - lightness * saturation;
  const second = 2 * lightness - first;
  const channel = (t: number): number => {
    let adjusted = t;
    if (adjusted < 0) {
      adjusted += 1;
    }
    if (adjusted > 1) {
      adjusted -= 1;
    }
    if (adjusted * 6 < 1) {
      return second + (first - second) * adjusted * 6;
    }
    if (adjusted * 2 < 1) {
      return first;
    }
    if (adjusted * 3 < 2) {
      return second + (first - second) * (2 / 3 - adjusted) * 6;
    }
    return second;
  };

  const rotatedRed = Math.round(channel(hueFraction + 1 / 3) * 255);
  const rotatedGreen = Math.round(channel(hueFraction) * 255);
  const rotatedBlue = Math.round(channel(hueFraction - 1 / 3) * 255);
  return `#${rotatedRed.toString(16).padStart(2, '0')}${rotatedGreen
    .toString(16).padStart(2, '0')}${rotatedBlue.toString(16).padStart(2, '0')}`;
}

// undefined for a non-hex or fully desaturated colour: a grey has no hue.
export function hueOf(color: string): number | undefined {
  if (!/^#[0-9a-fA-F]{6}$/.test(color)) return undefined;
  const red = parseInt(color.slice(1, 3), 16) / 255;
  const green = parseInt(color.slice(3, 5), 16) / 255;
  const blue = parseInt(color.slice(5, 7), 16) / 255;
  const max = Math.max(red, green, blue);
  const min = Math.min(red, green, blue);
  const span = max - min;
  if (span === 0) return undefined;
  const hue = max === red
    ? ((green - blue) / span) % 6
    : max === green
      ? (blue - red) / span + 2
      : (red - green) / span + 4;
  return ((hue * 60) % 360 + 360) % 360;
}
